function clearWifiCredential(){
 const field=$('#wifi-current-credential');if(field){field.value='';field.type='password'}
 for(const id of ['wifi-credential-reveal','wifi-credential-copy','wifi-credential-clear']){const button=$('#'+id);if(button){button.disabled=true;if(id==='wifi-credential-reveal')button.textContent='Reveal'}}
 const status=$('#wifi-credential-status');if(status)status.textContent='Credential cleared from the current view.';
}
async function requestWifiCredential(){
 const status=$('#wifi-credential-status');if(status)status.textContent='Requesting access from the operating system…';
 const requestButton=$('.audit-credential-controls button');if(requestButton)requestButton.disabled=true;
 try{
  let response=await api('get_current_wifi_credential',true);
  if(!response?.ok||typeof response.password!=='string'||!response.password){const reason=response?.reason||'The operating system returned no saved credential.';if(status)status.textContent=reason;toast(reason);return}
  const field=$('#wifi-current-credential');if(!field){response.password='';response=null;return}
  field.value=response.password;field.type='password';response.password='';response=null;
  for(const id of ['wifi-credential-reveal','wifi-credential-clear']){const button=$('#'+id);if(button)button.disabled=false}
  const copy=$('#wifi-credential-copy');if(copy)copy.disabled=true;
  if(status)status.textContent='Credential returned by the operating system and masked. It is transient and will clear when you leave this page or hide the window.';
 }catch(error){const message=error?.message||'The operating system denied credential access.';if(status)status.textContent=message;toast(message)}
 finally{if(requestButton)requestButton.disabled=false}
}
function toggleWifiCredential(){
 const field=$('#wifi-current-credential');if(!field||!field.value)return;
 const revealing=field.type==='password';field.type=revealing?'text':'password';
 const reveal=$('#wifi-credential-reveal');if(reveal)reveal.textContent=revealing?'Hide':'Reveal';
 const copy=$('#wifi-credential-copy');if(copy)copy.disabled=!revealing;
}
async function copyWifiCredential(){
 const field=$('#wifi-current-credential');if(!field||field.type!=='text'||!field.value){toast('Reveal the current credential before copying it.');return}
 try{if(navigator.clipboard?.writeText)await navigator.clipboard.writeText(field.value);else{field.focus();field.select();if(!document.execCommand('copy'))throw Error('Clipboard access is unavailable.')}toast('Current Wi-Fi credential copied.')}
 catch(error){toast(error?.message||'Clipboard access is unavailable; select the revealed value to copy it.')}
}
