const themeOrder=['dark','light','matrix','retro'];
function applyTheme(theme){state.theme=themeOrder.includes(theme)?theme:'dark';document.body.classList.remove('light','theme-matrix','theme-retro');if(state.theme==='light')document.body.classList.add('light');if(state.theme==='matrix')document.body.classList.add('theme-matrix');if(state.theme==='retro')document.body.classList.add('theme-retro');const names={dark:'Light',light:'Green Matrix',matrix:'Retro Classic',retro:'Dark'};const button=$('#theme');if(button)button.textContent=names[state.theme];syncMatrixRain()}
const matrixMotion=window.matchMedia?.('(prefers-reduced-motion: reduce)');const readPref=(key,fallback)=>{try{return localStorage.getItem(key)??fallback}catch(_){return fallback}},writePref=(key,value)=>{try{localStorage.setItem(key,value)}catch(_){}};let matrixPrefs={enabled:readPref('ws-matrix-rain','on')!=='off',intensity:readPref('ws-matrix-intensity','medium')},matrixFrame=null,matrixLast=0,matrixColumns=[];
function bindMatrixControls(){const enabled=$('#matrix-rain-enabled'),intensity=$('#matrix-intensity');if(enabled)enabled.onchange=()=>{matrixPrefs.enabled=enabled.checked;writePref('ws-matrix-rain',enabled.checked?'on':'off');syncMatrixRain()};if(intensity)intensity.onchange=()=>{matrixPrefs.intensity=intensity.value;writePref('ws-matrix-intensity',intensity.value);syncMatrixRain()}}
function syncMatrixRain(){const canvas=$('#matrix-rain');if(!canvas)return;const reduce=!!matrixMotion?.matches,active=state.theme==='matrix'&&matrixPrefs.enabled&&!reduce&&!document.hidden;canvas.style.display=active?'block':'none';canvas.style.opacity=matrixPrefs.intensity==='high'?'.25':matrixPrefs.intensity==='low'?'.09':'.16';if(active&&!matrixFrame){resizeMatrixCanvas();matrixFrame=requestAnimationFrame(drawMatrixRain)}else if(!active&&matrixFrame){cancelAnimationFrame(matrixFrame);matrixFrame=null}}
function resizeMatrixCanvas(){const canvas=$('#matrix-rain'),ctx=canvas?.getContext('2d');if(!canvas||!ctx)return;const width=window.innerWidth,height=window.innerHeight;canvas.width=Math.min(width,1920);canvas.height=Math.min(height,1200);const font=15;ctx.font=`${font}px monospace`;matrixColumns=Array.from({length:Math.ceil(canvas.width/(font*1.15))},()=>Math.random()*-50);canvas.dataset.font=String(font)}
function drawMatrixRain(now){const canvas=$('#matrix-rain'),ctx=canvas?.getContext('2d');if(!canvas||!ctx||state.theme!=='matrix'||!matrixPrefs.enabled||matrixMotion?.matches||document.hidden){matrixFrame=null;return}matrixFrame=requestAnimationFrame(drawMatrixRain);if(now-matrixLast<55)return;matrixLast=now;const font=Number(canvas.dataset.font)||15;ctx.fillStyle='rgba(3,8,5,.12)';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.font=`${font}px monospace`;for(let i=0;i<matrixColumns.length;i++){const y=matrixColumns[i]*font;ctx.fillStyle=i%8===0?'rgba(179,255,190,.82)':'rgba(48,190,78,.55)';ctx.fillText('01ﾊﾐｳｼﾄﾈﾆｻﾎﾓﾘ',i*font*1.15,y);if(y>canvas.height&&Math.random()>.98)matrixColumns[i]=0;else matrixColumns[i]+=.55+Math.random()*.7}}
window.addEventListener('resize',()=>{if(state.theme==='matrix'&&matrixPrefs.enabled&&!matrixMotion?.matches)resizeMatrixCanvas()});document.addEventListener('visibilitychange',()=>{syncMatrixRain();if(document.hidden)clearWifiCredential()});matrixMotion?.addEventListener?.('change',syncMatrixRain);
