async function labSimulator(){let snapshot;try{snapshot=await api('live_snapshot')}catch(e){snapshot={wifi:{nearby_aps:[],state:'unavailable',error:e.message}}}const aps=snapshot.wifi?.nearby_aps||[];if(state.pendingLabSsid){if(!labAPs.includes(state.pendingLabSsid))labAPs.push(state.pendingLabSsid);state.pendingLabSsid=''}return `<div class="hero lab-hero"><div class="eyebrow">ISOLATED TRAINING WORKSPACE</div><h2>Wireless behavior simulator</h2><div class="muted">Every action on this page is software-only. It never transmits frames, starts an access point, changes firmware, controls physical LEDs, joins a network, or saves credentials.</div><span class="sim-label">SIMULATION · NO RADIO ACTIVITY</span></div>
<div class="grid g2"><div class="panel"><div class="panel-head"><b>Passive deauthentication / PMF exposure review</b><span class="badge">OBSERVATIONS ONLY</span></div><div class="panel-body"><p class="muted">Uses only the current OS scan. Ordinary scans do not expose PMF negotiation details or client behavior, so unavailable evidence stays unknown.</p><div class="kpi">Observed nearby BSSIDs <b>${aps.length}</b></div><div class="kpi">PMF enforcement exposed by scan <b>Not exposed</b></div><div class="kpi">Deauthentication test performed <b>No · passive only</b></div><div class="table-wrap"><table class="table"><thead><tr><th>Observed AP</th><th>BSSID</th><th>PMF evidence</th></tr></thead><tbody>${aps.map(a=>`<tr><td>${ssidLabel(a)}</td><td class="mono">${esc(a.bssid||'Not exposed')}</td><td>Unknown · OS scan does not expose PMF enforcement</td></tr>`).join('')||'<tr><td colspan="3">No nearby AP observations are currently available.</td></tr>'}</tbody></table></div><div class="notice" style="margin-top:10px">Coverage is limited to APs and channels returned by the host OS at ${esc(snapshot.wifi?.observed_at||'an unavailable observation time')}. This is not an all-networks test.</div></div></div>
<div class="panel"><div class="panel-head"><b>Beacon concepts</b><span class="badge">SIMULATED APs ONLY</span></div><div class="panel-body form"><div class="field"><label>SSID source</label><select id="lab-source" onchange="setLabSource()"><option value="defaults">Default training list</option><option value="nearby">Clone a nearby observed name</option><option value="custom">Custom training name</option></select></div><div id="lab-source-detail"><div class="field"><label>Simulated profile</label><select id="lab-default"><option>TrainingNet</option><option>Guest WiFi Lab</option><option>Secure Office Demo</option></select></div></div><button class="primary" onclick="addLabBeacon()">Add simulated AP</button><div class="notice">Names appear only in this simulator. No beacon is broadcast and simulated entries never appear in Wi-Fi Discovery, assessment evidence, or reports.</div><div id="lab-beacons" class="sim-list">${renderLabAPs()}</div></div></div></div>
<div class="grid g2" style="margin-top:14px"><div class="panel"><div class="panel-head"><b>Captive portal awareness exercise</b><span class="badge">LOCAL PREVIEW</span></div><div class="panel-body form"><div class="field"><label>Training template</label><select id="lab-template" onchange="setLabTemplate(this.value)"><option value="minimal">Minimal sign-in awareness</option><option value="travel">Travel Wi-Fi warning</option><option value="workplace">Workplace training portal</option></select></div><div id="portal-preview" class="portal-preview">${portalPreview(labTemplate)}</div><form class="dummy-form" onsubmit="return submitDummy(event)"><label>Dummy username<input autocomplete="off" placeholder="training-user"></label><label>Dummy password<input type="password" autocomplete="new-password" placeholder="Dummy only"></label><button class="ghost" type="submit">Test local interaction</button></form><div id="dummy-result" class="muted">Input stays in the page and is immediately discarded on submit. Do not enter real credentials.</div></div></div>
<div class="panel"><div class="panel-head"><b>Hardware features</b><span class="badge">NOT CONFIGURED</span></div><div class="panel-body"><div class="kpi">OTA firmware update <b>Unavailable · no device integration</b></div><div class="muted">No firmware update is offered. Device model, signed update source, integrity verification and authenticated updater are not configured.</div><div class="kpi" style="margin-top:12px">Physical LED control <b>Unavailable · no device integration</b></div><button class="ghost" onclick="toggleLabLED()">Toggle simulated lab indicator</button><div id="lab-led" class="lab-led"><i></i><span>LAB INDICATOR · SIMULATED OFF</span></div><div class="muted">This indicator is a visual demo only; it does not control a physical device.</div></div></div></div>`}
function renderLabAPs(){return labAPs.length?labAPs.map((x,i)=>`<div class="sim-ap"><span><b>${esc(x)}</b><small>SIMULATED SSID · NOT BROADCAST</small></span><button class="ghost" onclick="removeLabBeacon(${i})">Remove</button></div>`).join(''):'<div class="empty">No simulated AP profiles added.</div>'}
function setLabSource(){const mode=$('#lab-source').value,box=$('#lab-source-detail');if(mode==='nearby'){api('live_snapshot').then(s=>{const a=s.wifi?.nearby_aps||[];box.innerHTML=`<div class="field"><label>Observed name to use in simulation</label><select id="lab-nearby">${a.map((x,i)=>`<option value="${i}">${ssidLabel(x)} · ${esc(x.bssid||'BSSID unavailable')}</option>`).join('')||'<option value="">No observed SSIDs available</option>'}</select></div><div class="muted">Only the SSID text is copied. No live network is cloned or emulated on air.</div>`}).catch(e=>box.textContent=e.message)}else if(mode==='custom')box.innerHTML='<div class="field"><label>Custom training SSID</label><input id="lab-custom" maxlength="32" placeholder="Training example"></div>';else box.innerHTML='<div class="field"><label>Simulated profile</label><select id="lab-default"><option>TrainingNet</option><option>Guest WiFi Lab</option><option>Secure Office Demo</option></select></div>'}
function addLabBeacon(){let mode=$('#lab-source')?.value||'defaults',name=mode==='nearby'?($('#lab-nearby')?.selectedOptions[0]?.textContent.split(' · ')[0]||''):mode==='custom'?$('#lab-custom')?.value.trim():$('#lab-default')?.value;if(!name){toast('Choose or enter a simulated SSID');return}if([...name].length>32){toast('SSID exceeds the 32 character limit');return}labAPs.push(name);$('#lab-beacons').innerHTML=renderLabAPs()}
function removeLabBeacon(i){labAPs.splice(i,1);$('#lab-beacons').innerHTML=renderLabAPs()}
function portalPreview(t){const names={minimal:['Network sign-in','Review the network name before entering information.'],travel:['Travel Wi-Fi safety check','Public networks may imitate familiar names. Verify the provider independently.'],workplace:['Workplace security learning','This training preview does not authenticate or submit credentials.']};let x=names[t]||names.minimal;return `<div class="portal-card"><div class="portal-mark">W</div><h3>${esc(x[0])}</h3><p>${esc(x[1])}</p><span>PREVIEW ONLY · NO SERVER</span></div>`}
function setLabTemplate(t){labTemplate=t;$('#portal-preview').innerHTML=portalPreview(t);$('#dummy-result').textContent='Input stays in the page and is immediately discarded on submit. Do not enter real credentials.'}
function submitDummy(e){e.preventDefault();const f=e.currentTarget;for(const x of f.querySelectorAll('input'))x.value='';$('#dummy-result').textContent='Training interaction recorded only as a local visual event; submitted values were cleared and not stored or transmitted.';return false}
function toggleLabLED(){const el=$('#lab-led');el.classList.toggle('on');el.querySelector('span').textContent='LAB INDICATOR · SIMULATED '+(el.classList.contains('on')?'ON':'OFF')}
async function awarenessTraining(){state.awarenessSummary=await api('awareness_training_summary');if(state.awarenessSummary?.status!=='active')state.awarenessSession=null;state.awarenessHistory=await api('awareness_training_history');const s=state.awarenessSummary||{},active=s.status==='active',history=state.awarenessHistory||[];const counts=s.events||{};return `<div class="hero"><h2>Security awareness training</h2><div class="muted">A fixed, fictional exercise hosted on this computer only. It does not send email or messages and has no credential or free-text fields.</div></div><div class="notice">The server binds only to 127.0.0.1. A random session token appears in the temporary local URL; it is held in memory and only its SHA-256 hash is persisted. Event records contain visit, click, and synthetic yes/no counts without IP addresses or submitted text.</div><div class="panel" style="margin-top:14px"><div class="panel-head"><b>Local training session</b><span>${badge(s.status||'not started')}</span></div><div class="panel-body"><label for="awareness-duration">Session duration</label><select id="awareness-duration"><option value="300">5 minutes</option><option value="900" selected>15 minutes</option><option value="1800">30 minutes</option></select>${active?`<div class="step"><div class="kpi">Session ID <b class="mono">${esc(s.session_id)}</b></div><div class="kpi">Expires <b>${esc(s.expires_at)}</b></div><div class="kpi">Local host <b>${esc(s.host)}:${esc(s.port)}</b></div><div class="kpi">Session link <b><a href="${esc(state.awarenessSession?.url||'')}" target="_blank" rel="noopener noreferrer">Open local exercise</a></b></div><div class="grid g4"><div class="card"><div class="label">Visits</div><div class="metric">${counts.visit||0}</div></div><div class="card"><div class="label">Clicks</div><div class="metric">${counts.click||0}</div></div><div class="card"><div class="label">Synthetic yes</div><div class="metric">${counts.synthetic_yes||0}</div></div><div class="card"><div class="label">Synthetic no</div><div class="metric">${counts.synthetic_no||0}</div></div></div><button class="ghost" onclick="refreshAwareness()">Refresh analytics</button><button class="danger" onclick="stopAwareness()">Stop session now</button></div>`:`<label class="check"><input id="awareness-authorized" type="checkbox"> I am authorized to operate this local training exercise.</label><button class="primary" onclick="startAwareness()">Start loopback-only session</button>${state.awarenessSession?.url?`<div class="notice" style="margin-top:12px">Session URL: <code>${esc(state.awarenessSession.url)}</code>. Treat it as a temporary access link and share only with intended local participants.</div>`:''}`}</div></div><div class="panel" style="margin-top:14px"><div class="panel-head"><div><b>Session history</b><div class="muted">Inactive sessions older than 90 days can be deleted.</div></div><span>${history.length} recorded sessions</span></div><div class="panel-body table-wrap"><table class="table"><thead><tr><th>Session</th><th>Status</th><th>Started</th><th>Ended</th><th>Visits</th><th>Clicks</th><th>Yes / No</th></tr></thead><tbody>${history.map(x=>`<tr><td class="mono">${esc(x.id)}</td><td>${badge(x.status)}</td><td>${esc(x.created_at)}</td><td>${esc(x.ended_at||'Not ended')}</td><td>${x.events.visit}</td><td>${x.events.click}</td><td>${x.events.synthetic_yes} / ${x.events.synthetic_no}</td></tr>`).join('')||'<tr><td colspan="7">No training sessions are stored.</td></tr>'}</tbody></table><button class="ghost" onclick="purgeAwarenessHistory()">Delete inactive history older than 90 days</button></div></div>`}
async function startAwareness(){if(!$('#awareness-authorized')?.checked){toast('Confirm authorization for this local exercise');return}try{state.awarenessSession=await api('start_awareness_training',Number($('#awareness-duration')?.value||900));state.awarenessSummary=state.awarenessSession;state.awarenessHistory=await api('awareness_training_history');toast('Loopback training session started.');await render()}catch(e){toast(e.message||String(e))}}
async function refreshAwareness(){try{state.awarenessSummary=await api('awareness_training_summary');state.awarenessHistory=await api('awareness_training_history');await render()}catch(e){toast(e.message||String(e))}}
async function stopAwareness(){try{state.awarenessSummary=await api('stop_awareness_training');state.awarenessSession=null;state.awarenessHistory=await api('awareness_training_history');toast('Training session stopped.');await render()}catch(e){toast(e.message||String(e))}}
async function purgeAwarenessHistory(){if(!confirm('Delete inactive awareness sessions and their synthetic event counts older than 90 days?'))return;try{const result=await api('purge_awareness_training_history',90);state.awarenessHistory=await api('awareness_training_history');toast(`Deleted ${result.deleted_sessions} old session(s).`);await render()}catch(e){toast(e.message||String(e))}}
async function lanMessaging(){state.lanReceivers=await api('enrolled_lan_receivers');state.lanMessageHistory=await api('lan_message_history');const receivers=state.lanReceivers||[],history=state.lanMessageHistory||[],options=receivers.map(r=>`<option value="${esc(r.enrollment_id)}">${esc(r.name)} · ${esc(r.receiver_id)} · ${esc(r.endpoint)}</option>`).join('');return `<div class="hero"><h2>LAN Messaging</h2><div class="muted">Send a short announcement only to a compatible receiver you explicitly enroll.</div></div><div class="notice">A receiver must run the WiFiSentinel receiver client. Remote endpoints require HTTPS with a pinned certificate and a shared enrollment token. Tokens stay in memory only and must be re-entered after app restart. An acknowledgement means the receiver accepted the message; it does not prove an OS notification was displayed or that a person read it. Unknown devices receive nothing.</div><div class="grid g2" style="margin-top:14px"><div class="panel"><div class="panel-head"><b>Enroll receiver</b><span class="badge">EXPLICIT ENROLLMENT</span></div><div class="panel-body"><label for="receiver-name">Display name</label><input id="receiver-name" maxlength="100" placeholder="Lab laptop"><label for="receiver-id" style="margin-top:10px">Receiver ID</label><input id="receiver-id" maxlength="64" placeholder="lab-laptop"><label for="receiver-endpoint" style="margin-top:10px">HTTPS origin</label><input id="receiver-endpoint" type="url" placeholder="https://192.168.1.20:8765"><label for="receiver-pin" style="margin-top:10px">TLS certificate SHA-256 fingerprint</label><input id="receiver-pin" maxlength="95" placeholder="64 hexadecimal characters"><label for="receiver-token" style="margin-top:10px">Shared enrollment token</label><input id="receiver-token" type="password" autocomplete="new-password" placeholder="At least 32 random bytes"><label class="check"><input id="receiver-authorized" type="checkbox"> I administer or am authorized to enroll this receiver.</label><button class="primary" onclick="enrollLanReceiver()">Enroll receiver in memory</button><p class="muted">Never use a real password as the receiver token. Generate a random token and set the same value in the receiver process environment.</p></div></div><div class="panel"><div class="panel-head"><b>Enrolled receivers</b><span>${receivers.length} available</span></div><div class="panel-body">${receivers.map(r=>`<div class="step"><div class="split"><b>${esc(r.name)}</b><button class="ghost" onclick="forgetLanReceiver('${esc(r.enrollment_id)}')">Forget</button></div><div class="muted">${esc(r.receiver_id)} · ${esc(r.endpoint)}</div><div class="muted mono">Pinned certificate ${esc(r.certificate_sha256)}</div><div class="muted">Token held in memory only.</div></div>`).join('')||'<div class="empty">No compatible receivers are enrolled.</div>'}</div></div></div><div class="panel" style="margin-top:14px"><div class="panel-head"><b>Send announcement</b><span class="badge">MAX 1000 CHARACTERS · 5 MINUTE EXPIRY</span></div><div class="panel-body"><label for="message-receiver">Enrolled receiver</label><select id="message-receiver">${options||'<option value="">No receiver enrolled</option>'}</select><label for="message-title" style="margin-top:10px">Title · 80 characters</label><input id="message-title" maxlength="80" placeholder="Maintenance notice"><label for="message-body" style="margin-top:10px">Message · 1000 characters</label><textarea id="message-body" maxlength="1000" placeholder="Write a brief plain-text announcement."></textarea><label class="check"><input id="message-authorized" type="checkbox"> I authorize sending this announcement to the selected enrolled receiver.</label><button class="primary" onclick="sendLanAnnouncement()" ${receivers.length?'':'disabled'}>Send and require signed acknowledgement</button></div></div><div class="panel" style="margin-top:14px"><div class="panel-head"><b>Delivery history</b><span>${history.length} attempts</span></div><div class="panel-body table-wrap"><table class="table"><thead><tr><th>Status</th><th>Receiver</th><th>Message ID</th><th>Sent</th><th>Acknowledged</th><th>Evidence</th></tr></thead><tbody>${history.map(x=>`<tr><td>${badge(x.status)}</td><td>${esc(x.receiver_name)} · ${esc(x.receiver_id)}</td><td class="mono">${esc(x.message_id||'No receiver acknowledgement')}</td><td>${esc(x.sent_at)}</td><td>${esc(x.received_at||'Not acknowledged')}</td><td class="mono">${esc(x.content_sha256)}</td></tr>`).join('')||'<tr><td colspan="6">No messages have been sent.</td></tr>'}</tbody></table><div class="notice">Message text is not retained by WiFiSentinel. History stores only a SHA-256 digest, receiver, status, and verified acknowledgement metadata.</div></div></div>`}
async function enrollLanReceiver(){if(!$('#receiver-authorized')?.checked){toast('Confirm authority to enroll this receiver.');return}try{const result=await api('enroll_lan_receiver',$('#receiver-name').value,$('#receiver-endpoint').value,$('#receiver-token').value,$('#receiver-pin').value,$('#receiver-id').value,true);$('#receiver-token').value='';state.lanReceivers=await api('enrolled_lan_receivers');toast(`Enrolled ${result.name}; token is held in memory only.`);await render()}catch(e){toast(e.message||String(e))}}
async function forgetLanReceiver(id){if(!confirm('Forget this receiver from this WiFiSentinel session? The receiver token will be removed from memory; rotate the token separately to revoke other copies.'))return;try{await api('forget_lan_receiver',id);state.lanReceivers=await api('enrolled_lan_receivers');await render()}catch(e){toast(e.message||String(e))}}
async function sendLanAnnouncement(){if(!$('#message-authorized')?.checked){toast('Confirm authorization before sending.');return}const receiver=$('#message-receiver')?.value,title=$('#message-title')?.value||'',body=$('#message-body')?.value||'';if(!receiver||!confirm('Send this announcement to the selected enrolled receiver now?'))return;try{const result=await api('send_lan_announcement',receiver,title,body,true);state.lanMessageHistory=await api('lan_message_history');toast(result.ok?'Receiver accepted the announcement.':'No verified receiver acknowledgement.');await render()}catch(e){toast(e.message||String(e))}}
let liveTimer=null,liveWarmupTimer=null,liveRequestId=0,liveActiveRequest=null,liveQueuedForce=false;
function stopLivePolling(){liveRequestId++;liveActiveRequest=null;liveQueuedForce=false;if(liveTimer){clearInterval(liveTimer);liveTimer=null}if(liveWarmupTimer){clearTimeout(liveWarmupTimer);liveWarmupTimer=null}}
async function refreshLiveNow(force=false,attempt=0,manual=force,requestId=null){
 if(requestId===null){if(liveActiveRequest!==null){if(force)liveQueuedForce=true;return}requestId=++liveRequestId;liveActiveRequest=requestId}else if(requestId!==liveRequestId)return;
 let retryScheduled=false;
 try{
  if(force&&attempt===0)await api('refresh_live');
  const snap=await api('live_snapshot');if(requestId!==liveRequestId)return;state.networkSnapshot=snap;
  if(state.page==='dashboard'){
   const aps=snap.wifi?.nearby_aps||[];aps.forEach((ap,index)=>{ap._observation_index=index});
   let selected=aps.find(ap=>apIdentity(ap)===state.selectedApKey)||null;
   if(!selected&&state.selectedApRecord){const match=window.WiFiSentinelCapabilityState.matchObservationIndex(state.selectedApRecord,aps);if(match>=0)selected=aps[match]}
   if(!selected&&!state.selectedApRecord)selected=aps[0]||null;
   if(selected){state.selectedApKey=apIdentity(selected);state.selectedApRecord={...selected}}
   else {state.selectedApKey=null;state.aid=null;state.networkReview=null;state.networkAI=null}
   const list=$('#network-list');if(list)list.innerHTML=renderNetworkRows(filteredNetworks(),state.selectedApKey);
   const detail=$('#network-details'),w=snap.wifi||{};
   if(detail)detail.innerHTML=selected?renderNetworkDetail(selected,w,scanSource(w)):'<div class="empty">The previously selected observation is no longer present in the current scan. Select a current row to continue.</div>';
   const status=$('#network-live-state'),stamp=$('#network-last-scan'),error=$('#network-scan-error');
   if(status)status.textContent=window.WiFiSentinelCapabilityState.scanStatus(snap);
   if(stamp)stamp.textContent=`Last successful scan ${w.observed_at||snap.observed_at||'pending'}${snap.cache_age_ms!=null&&snap.collection_error?` · last good ${Math.round(snap.cache_age_ms/1000)}s ago`:''}`;
   if(error){error.textContent=window.WiFiSentinelCapabilityState.scanMessage(snap,w);error.style.display=error.textContent?'block':'none'}
  }else if((state.page==='devices'||state.page==='map')&&!snap.refreshing)await render();
  if(snap.refreshing&&attempt<60){retryScheduled=true;setTimeout(()=>refreshLiveNow(false,attempt+1,manual,requestId),350)}
 }catch(e){if(manual)toast(e.message||String(e))}
 finally{if(!retryScheduled&&liveActiveRequest===requestId){liveActiveRequest=null;if(liveQueuedForce){liveQueuedForce=false;refreshLiveNow(true)}}}
}
function startLivePolling(){stopLivePolling();if(['dashboard','devices','map'].includes(state.page)){liveWarmupTimer=setTimeout(()=>{liveWarmupTimer=null;if(!document.hidden)refreshLiveNow()},500);liveTimer=setInterval(()=>{if(!document.hidden)refreshLiveNow()},12000)}}
const _render=render;
render=async function(){clearWifiCredential();stopLivePolling();await _render();startLivePolling()};
$('#theme').onclick=toggleTheme;$('#refresh').onclick=()=>['dashboard','devices','map'].includes(state.page)?refreshLiveNow(true):render();nav();if(B){api('settings').then(s=>applyTheme(s.theme)).catch(()=>{});render()}else $('#app').innerHTML='<div class="content page-loading"><div class="loading-card"><span class="spinner"></span><div><b>Starting local engine</b><div class="muted">Waiting for the desktop bridge.</div></div></div></div>';window.addEventListener('pywebviewready',()=>{B=window.pywebview.api;render();api('settings').then(s=>applyTheme(s.theme)).catch(()=>{})});
